package li.cil.oc.server.component;

import li.cil.oc.Settings;
import li.cil.oc.api.internal.Database;
import li.cil.oc.api.machine.*;
import li.cil.oc.api.network.*;
import li.cil.oc.api.prefab.ItemStackArrayValue;
import li.cil.oc.util.InventoryUtils;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.items.IItemHandler;
import java.util.*;
import java.util.function.Function;

/** Original world inventory analytics. Agent-specific control is exposed only by its agent subtype. */
public class UpgradeInventoryController extends UpgradeBase {
    public UpgradeInventoryController(EnvironmentHost host){super(host,"inventory_controller","Inventory controller","Item Cataloguer R1",false);}
    @Override protected Direction side(Arguments args,int index){int value=args.checkInteger(index);if(value<0||value>5)throw new IllegalArgumentException("invalid side");if(host instanceof li.cil.oc.api.internal.Robot&&value!=0&&value!=1&&value!=3)throw new IllegalArgumentException("unsupported side");Direction side=Direction.from3DDataValue(value);return host instanceof li.cil.oc.api.internal.Robot robot?robot.toGlobal(side):side;}
    protected Object[] inventory(Arguments args,Function<IItemHandler,Object[]> action){Direction direction=side(args,0);var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(direction),direction.getOpposite());return source.isPresent()&&mayInteract(source.get())?action.apply(source.get().inventory()):new Object[]{null,"no inventory"};}
    protected Database database(String address){Node target=node().network()==null?null:node().network().node(address);if(!(target instanceof Component))throw new IllegalArgumentException("no such component");if(!(target.host() instanceof UpgradeDatabase database))throw new IllegalArgumentException("not a database");return database;}
    @Callback(doc="function(side:number):number -- Get the number of slots in the inventory on the specified side of the device.") public Object[] getInventorySize(Context context,Arguments args){return inventory(args,handler->new Object[]{handler.getSlots()});}
    @Callback(doc="function(side:number, slot:number):number -- Get number of items in the specified slot of the inventory on the specified side of the device.") public Object[] getSlotStackSize(Context context,Arguments args){return inventory(args,handler->new Object[]{handler.getStackInSlot(slot(args,1,handler.getSlots())).getCount()});}
    @Callback(doc="function(side:number, slot:number):number -- Get the maximum number of items in the specified slot of the inventory on the specified side of the device.") public Object[] getSlotMaxStackSize(Context context,Arguments args){return inventory(args,handler->{ItemStack stack=handler.getStackInSlot(slot(args,1,handler.getSlots()));return new Object[]{stack.isEmpty()?0:stack.getMaxStackSize()};});}
    @Callback(doc="function(side:number, slotA:number, slotB:number[, checkNBT:boolean=false]):boolean -- Get whether the items in the two specified slots of the inventory on the specified side of the device are of the same type.") public Object[] compareStacks(Context context,Arguments args){return inventory(args,handler->{ItemStack a=handler.getStackInSlot(slot(args,1,handler.getSlots())),b=handler.getStackInSlot(slot(args,2,handler.getSlots()));return new Object[]{a==b||InventoryUtils.haveSameItemType(a,b,args.optBoolean(3,false))};});}
    @Callback(doc="function(side:number, slot:number, dbAddress:string, dbSlot:number[, checkNBT:boolean=false]):boolean -- Compare an item in the specified slot in the inventory on the specified side with one in the database with the specified address.") public Object[] compareStackToDatabase(Context context,Arguments args){return inventory(args,handler->{ItemStack stack=handler.getStackInSlot(slot(args,1,handler.getSlots()));Database database=database(args.checkString(2));return new Object[]{InventoryUtils.haveSameItemType(stack,Objects.requireNonNullElse(database.getStackInSlot(slot(args,3,database.size())),ItemStack.EMPTY),args.optBoolean(4,false))};});}
    @Callback(doc="function(side:number, slotA:number, slotB:number):boolean -- Get whether the items in the two specified slots of the inventory on the specified side of the device are equivalent (have shared OreDictionary IDs).") public Object[] areStacksEquivalent(Context context,Arguments args){return inventory(args,handler->{ItemStack a=handler.getStackInSlot(slot(args,1,handler.getSlots())),b=handler.getStackInSlot(slot(args,2,handler.getSlots()));return new Object[]{a==b||!a.isEmpty()&&!b.isEmpty()&&a.getTags().anyMatch(b::is)};});}
    @Callback(doc="function(side:number, slot:number):table -- Get a description of the stack in the inventory on the specified side of the device.") public Object[] getStackInSlot(Context context,Arguments args){return Settings.get().allowItemStackInspection?inventory(args,handler->new Object[]{handler.getStackInSlot(slot(args,1,handler.getSlots())).copy()}):new Object[]{null,"not enabled in config"};}
    @Callback(doc="function(side:number):userdata -- Get a description of all stacks in the inventory on the specified side of the device.") public Object[] getAllStacks(Context context,Arguments args){return Settings.get().allowItemStackInspection?inventory(args,handler->{ItemStack[] stacks=new ItemStack[handler.getSlots()];for(int i=0;i<stacks.length;i++)stacks[i]=handler.getStackInSlot(i).copy();return new Object[]{new ItemStackArrayValue(stacks,host.world().registryAccess())};}):new Object[]{null,"not enabled in config"};}
    @Callback(doc="function(side:number):string -- Get the the name of the inventory on the specified side of the device.") public Object[] getInventoryName(Context context,Arguments args){if(!Settings.get().allowItemStackInspection)return new Object[]{null,"not enabled in config"};Direction side=side(args,0);var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(side),side.getOpposite());if(source.isEmpty()||!mayInteract(source.get()))return new Object[]{null,"no inventory"};return new Object[]{source.get() instanceof InventoryUtils.BlockInventorySource block?BuiltInRegistries.BLOCK.getKey(host.world().getBlockState(block.position()).getBlock()).toString():BuiltInRegistries.ENTITY_TYPE.getKey(((InventoryUtils.EntityInventorySource)source.get()).entity().getType()).toString()};}
    @Callback(doc="function(side:number, slot:number, dbAddress:string, dbSlot:number):boolean -- Store an item stack description in the specified slot of the database with the specified address.") public Object[] store(Context context,Arguments args){side(args,0);String address=args.checkString(2);return inventory(args,handler->{ItemStack stack=handler.getStackInSlot(slot(args,1,handler.getSlots()));Database database=database(address);int to=slot(args,3,database.size());ItemStack old=database.getStackInSlot(to);database.setStackInSlot(to,stack.copy());return new Object[]{old!=null&&!old.isEmpty()};});}

    public static class Agent extends UpgradeInventoryController {
        protected final li.cil.oc.api.internal.Agent agent;
        public Agent(EnvironmentHost host){super(host);agent=(li.cil.oc.api.internal.Agent)host;}
        protected int internalSlot(Arguments args,int index){return defined(args,index)?slot(args,index,agent.mainInventory().getContainerSize()):agent.selectedSlot();}
        protected List<Integer> insertionSlots(){List<Integer> result=new ArrayList<>();for(int i=agent.selectedSlot();i<agent.mainInventory().getContainerSize();i++)result.add(i);for(int i=0;i<agent.selectedSlot();i++)result.add(i);return result;}
        @Callback(doc="function([slot:number]):table -- Get a description of the stack in the specified slot or the selected slot.") public Object[] getStackInInternalSlot(Context context,Arguments args){return Settings.get().allowItemStackInspection?new Object[]{agent.mainInventory().getItem(internalSlot(args,0)).copy()}:new Object[]{null,"not enabled in config"};}
        @Callback(doc="function(otherSlot:number):boolean -- Get whether the stack in the selected slot is equivalent to the item in the specified slot (have shared OreDictionary IDs).") public Object[] isEquivalentTo(Context context,Arguments args){ItemStack a=agent.mainInventory().getItem(agent.selectedSlot()),b=agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize()));return new Object[]{a.isEmpty()&&b.isEmpty()||!a.isEmpty()&&!b.isEmpty()&&a.getTags().anyMatch(b::is)};}
        @Callback(doc="function(slot:number, dbAddress:string, dbSlot:number):boolean -- Store an item stack description in the specified slot of the database with the specified address.") public Object[] storeInternal(Context context,Arguments args){ItemStack stack=agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize()));Database target=database(args.checkString(1));int index=slot(args,2,target.size());ItemStack old=target.getStackInSlot(index);target.setStackInSlot(index,stack.copy());return new Object[]{old!=null&&!old.isEmpty()};}
        @Callback(doc="function(slot:number, dbAddress:string, dbSlot:number[, checkNBT:boolean=false]):boolean -- Compare an item in the specified slot with one in the database with the specified address.") public Object[] compareToDatabase(Context context,Arguments args){ItemStack stack=agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize()));Database target=database(args.checkString(1));return new Object[]{InventoryUtils.haveSameItemType(stack,Objects.requireNonNullElse(target.getStackInSlot(slot(args,2,target.size())),ItemStack.EMPTY),args.optBoolean(3,false))};}
        private Object[] adjacent(Direction facing,Direction access,Function<IItemHandler,Object[]> action){var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(facing),access);return source.isPresent()&&mayInteract(source.get())?action.apply(source.get().inventory()):new Object[]{null,"no inventory"};}
        private int sideValue(Arguments args,int index){int value=args.checkInteger(index);if(value<0||value>5)throw new IllegalArgumentException("invalid side");return value;}
        @Callback(doc="function(facing:number, slot:number[, count:number[, fromSide:number]]):boolean -- Drops the selected item stack into the specified slot of an inventory.") public Object[] dropIntoSlot(Context context,Arguments args){
            Direction facing=side(args,0);int count=Math.max(0,Math.min(64,args.optInteger(2,64)));
            Direction access=args.count()>3?Direction.from3DDataValue(sideValue(args,3)):facing.getOpposite();
            ItemStack stack=agent.mainInventory().getItem(agent.selectedSlot());if(stack.isEmpty())return new Object[]{false};
            return adjacent(facing,access,target->{
                if(!InventoryUtils.insertIntoInventorySlot(stack,target,slot(args,1,target.getSlots()),count,false))return new Object[]{false,"inventory full/invalid slot"};
                if(stack.isEmpty())agent.mainInventory().setItem(agent.selectedSlot(),ItemStack.EMPTY);else agent.mainInventory().setChanged();
                changed();context.pause(Settings.get().config.getDouble("robot.delays.drop"));return new Object[]{true};
            });
        }
        @Callback(doc="function(facing:number, slot:number[, count:number[, fromSide:number]]):boolean -- Sucks items from the specified slot of an inventory.") public Object[] suckFromSlot(Context context,Arguments args){
            Direction facing=side(args,0);int count=Math.max(0,Math.min(64,args.optInteger(2,64)));
            Direction access=args.count()>3?Direction.from3DDataValue(sideValue(args,3)):facing.getOpposite();
            return adjacent(facing,access,source->{int moved=InventoryUtils.extractFromInventorySlot((stack,simulate)->InventoryUtils.insertIntoInventory(stack,InventoryUtils.asItemHandler(agent.mainInventory()),stack.getCount(),simulate,insertionSlots()),source,slot(args,1,source.getSlots()),count);if(moved>0){changed();context.pause(Settings.get().config.getDouble("robot.delays.suck"));}return moved>0?new Object[]{moved}:new Object[]{false};});
        }
        private Object[] itemInventory(Arguments args,Function<IItemHandler,Object[]> action){IItemHandler handler=li.cil.oc.api.Driver.itemHandlerFor(agent.mainInventory().getItem(slot(args,0,agent.mainInventory().getContainerSize())),fakePlayer());return handler==null?new Object[]{0,"no item inventory"}:action.apply(handler);}
        @Callback(doc="function(slot:number):number -- The size of an item inventory in the specified slot.") public Object[] getItemInventorySize(Context context,Arguments args){return itemInventory(args,handler->new Object[]{handler.getSlots()});}
        @Callback(doc="function(inventorySlot:number, slot:number[, count:number=64]):number -- Drops an item from the selected slot into the specified slot in the item inventory.") public Object[] dropIntoItemInventory(Context context,Arguments args){return itemInventory(args,handler->{int moved=InventoryUtils.transferBetweenInventoriesSlots(InventoryUtils.asItemHandler(agent.mainInventory()),agent.selectedSlot(),handler,slot(args,1,handler.getSlots()),Math.max(0,Math.min(64,args.optInteger(2,64))));changed();return new Object[]{moved};});}
        @Callback(doc="function(inventorySlot:number, slot:number[, count:number=64]):number -- Sucks an item out of the specified slot in the item inventory.") public Object[] suckFromItemInventory(Context context,Arguments args){return itemInventory(args,handler->{int moved=InventoryUtils.extractFromInventorySlot((stack,simulate)->InventoryUtils.insertIntoInventory(stack,InventoryUtils.asItemHandler(agent.mainInventory()),stack.getCount(),simulate,insertionSlots()),handler,slot(args,1,handler.getSlots()),Math.max(0,Math.min(64,args.optInteger(2,64))));changed();return new Object[]{moved};});}
    }
    public static final class Robot extends Agent {
        public Robot(EnvironmentHost host){super(host);}
        @Callback(doc="function():boolean -- Swaps the equipped tool with the content of the currently selected inventory slot.") public Object[] equip(Context context,Arguments args){if(agent.mainInventory().getContainerSize()==0)return new Object[]{false};ItemStack equipped=agent.equipmentInventory().getItem(0),selected=agent.mainInventory().getItem(agent.selectedSlot());agent.equipmentInventory().setItem(0,selected);agent.mainInventory().setItem(agent.selectedSlot(),equipped);changed();return new Object[]{true};}
    }
}
